import React from "react";
import { describe, it, expect } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import { TextInput } from "../src/TextInput";
import { Greeting } from "../src/Greeting";
import { Footer } from "../src/Footer";

describe("existing components", () => {
  it("TextInput reports changes", () => {
    let v = ""; render(<TextInput label="Name" value="" onChange={(x) => (v = x)} />);
    fireEvent.change(screen.getByRole("textbox"), { target: { value: "abc" } }); expect(v).toBe("abc");
  });
  it("Greeting says hello", () => { render(<Greeting name="Ada" />); expect(screen.getByText("Hello, Ada!")).toBeTruthy(); });
  it("Footer renders", () => { render(<Footer />); expect(screen.getByText(/Agentoon demo/)).toBeTruthy(); });
});
